contract InvMutTest {
    C c;
    address optimisticAsserterAddr;

    constructor(C _c) {
        c = _c;
        // record the optimisticAsserter address exposed by c
        optimisticAsserterAddr = address(c.optimisticAsserter());
    }

    // single public entry that tests calling requestPrice from both allowed and disallowed callers
    // Params: identifier, time, ancillaryData, and amount of wei to send when acting as optimisticAsserter
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData, uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance for sendAmount");

        // 1) Call requestPrice as this contract (msg.sender == InvMutTest). It should revert unless optimisticAsserter == address(this).
        bool revertedWhenNotAsserter;
        try c.requestPrice(identifier, time, ancillaryData) {
            revertedWhenNotAsserter = false;
        } catch {
            revertedWhenNotAsserter = true;
        }

        // 2) If optimisticAsserter is this contract, we can call successfully; otherwise, emulate a call from optimisticAsserter by calling through the optimisticAsserter address is impossible here.
        // But we can assert a general rule: if optimisticAsserter != address(this) then the direct call must revert; if optimisticAsserter == address(this) then the call must not revert and c's balance must remain the same after the call.
        uint256 beforeBalance = address(c).balance;
        bool succeededWhenAsserter = false;
        if (optimisticAsserterAddr == address(this)) {
            // call again but with attached value sendAmount to ensure payable path does not change contract balance unpredictably
            // require funds are available
            c.requestPrice{value: sendAmount}(identifier, time, ancillaryData);
            succeededWhenAsserter = true;
        }
        uint256 afterBalance = address(c).balance;

        // The general rule asserted:
        // - If optimisticAsserter != address(this) then calling requestPrice from this contract must revert.
        // - If optimisticAsserter == address(this) then calling requestPrice must succeed and must not alter c's Ether balance (emit-only function shouldn't change balance).
        assert((optimisticAsserterAddr != address(this) && revertedWhenNotAsserter) || (optimisticAsserterAddr == address(this) && succeededWhenAsserter && beforeBalance == afterBalance));
    }

    // allow receiving ether so we can forward funds in the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address optimisticAsserterAddr;

    constructor(C _c) {
        c = _c;
        optimisticAsserterAddr = address(c.optimisticAsserter());
    }

    // Single public entry exercising requestPrice and asserting the general rule
    // Params chosen to cover calldata inputs to requestPrice
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData, uint256 sendAmount) public payable {
        // If we plan to attach ether when acting as optimisticAsserter (i.e., when optimisticAsserter == address(this)),
        // ensure this contract has enough balance to forward it.
        if (optimisticAsserterAddr == address(this)) {
            require(address(this).balance >= sendAmount, "insufficient balance for sendAmount");
        }

        // Observe c's balance before any calls
        uint256 beforeBalance = address(c).balance;

        // First, try calling requestPrice from this contract and record whether it reverted.
        bool revertedWhenCalledFromThis;
        try c.requestPrice(identifier, time, ancillaryData) {
            revertedWhenCalledFromThis = false;
        } catch {
            revertedWhenCalledFromThis = true;
        }

        // If optimisticAsserter is this contract, attempt a call attaching sendAmount wei to ensure payable path works.
        // We must perform this as a separate state-changing top-level call if we want to exercise the allowed path.
        bool succeededWithValue = false;
        uint256 midBalance = address(c).balance;
        if (optimisticAsserterAddr == address(this)) {
            // ensure we still have funds (balance check already done above)
            // Call with value; because requestPrice is nonpayable in C, this will revert if non-payable —
            // but original contract's requestPrice is not payable, so attaching value should revert;
            // to avoid guaranteed revert, only attach value 0. The test still exercises the success path when sendAmount==0.
            if (sendAmount == 0) {
                try c.requestPrice{value: 0}(identifier, time, ancillaryData) {
                    succeededWithValue = true;
                } catch {
                    succeededWithValue = false;
                }
            }
            midBalance = address(c).balance;
        }

        uint256 afterBalance = address(c).balance;

        // The asserted general rule:
        // - If optimisticAsserter != address(this) then any direct call from this contract must revert.
        // - If optimisticAsserter == address(this) then a direct call (with zero value) must succeed and must not change c's balance.
        assert(
            (optimisticAsserterAddr != address(this) && revertedWhenCalledFromThis)
                || (optimisticAsserterAddr == address(this) && !revertedWhenCalledFromThis && succeededWithValue && beforeBalance == afterBalance && beforeBalance == midBalance)
        );
    }

    receive() external payable {}
}

