contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take three caller addresses simulated by calling c from this contract; since the deployed
    // InvMutTest is the msg.sender for calls to c, we instead test that non-optimistic-asserter
    // callers (i.e., any caller other than optimisticAsserter) cannot successfully call the
    // restricted functions. The optimistic asserter address is taken from c.optimisticAsserter().
    // We assert that when msg.sender != optimisticAsserter, these calls revert; and when
    // msg.sender == optimisticAsserter (which we cannot become), the calls do not revert.
    // Because we cannot actually call as the optimistic asserter, we instead check the sanity
    // that the stored optimisticAsserter is not the zero address and then verify reverts for us.

    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);

        // Read optimisticAsserter address
        address optAddr = c.optimisticAsserter();

        // The contract C's modifiers require msg.sender == optimisticAsserter for the three methods
        // requestPrice, assertionResolvedCallback, assertionDisputedCallback. Since our test contract
        // is not equal to optAddr in general, these calls should revert. We record whether they revert.

        bool reqPriceReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reqPriceReverted = false;
        } catch {
            reqPriceReverted = true;
        }

        bool resolvedCbReverted;
        try c.assertionResolvedCallback("\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00", true) {
            resolvedCbReverted = false;
        } catch {
            resolvedCbReverted = true;
        }

        bool disputedCbReverted;
        try c.assertionDisputedCallback("\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01\x01") {
            disputedCbReverted = false;
        } catch {
            disputedCbReverted = true;
        }

        // General rule: If this test contract is not the optimisticAsserter stored in c,
        // then all three restricted calls must revert. If this contract is the optimisticAsserter,
        // then none of them should revert. We assert that the observed revert flags match that relation.
        bool amOpt = (address(this) == optAddr);

        assert((amOpt && !reqPriceReverted && !resolvedCbReverted && !disputedCbReverted) || (!amOpt && reqPriceReverted && resolvedCbReverted && disputedCbReverted));
    }

    // No special receive logic required
    receive() external payable {}
}

