contract InvMutTest {
    C c;
    address optimisticAsserter;

    constructor(C _c) { c = _c; optimisticAsserter = address(c.optimisticAsserter()); }

    // single public entrypoint for property-based test
    // params:
    // callerIsAsserter: if true, the test will attempt calls from the optimisticAsserter address via c (by simulating allowed caller)
    // We cannot change msg.sender for calls, but we can observe behavior by calling via the test contract.
    // To check the onlyOptimisticAsserter restriction, we call the three restricted functions and record whether they revert
    function run(bool pretendAsserter) public payable {
        require(true);

        // We'll attempt to call each restricted function and capture whether it reverts.
        bool reverted_requestPrice;
        bool reverted_assertionResolvedCallback;
        bool reverted_assertionDisputedCallback;

        // 1) requestPrice: expects onlyOptimisticAsserter => requires msg.sender == optimisticAsserter
        // Call from this contract (msg.sender != optimisticAsserter unless optimisticAsserter == address(this)).
        try c.requestPrice(bytes32(0x1234), uint256(0x42), "anc") {
            reverted_requestPrice = false;
        } catch {
            reverted_requestPrice = true;
        }

        // 2) assertionResolvedCallback
        try c.assertionResolvedCallback(bytes32(0xdead), true) {
            reverted_assertionResolvedCallback = false;
        } catch {
            reverted_assertionResolvedCallback = true;
        }

        // 3) assertionDisputedCallback
        try c.assertionDisputedCallback(bytes32(0xbeef)) {
            reverted_assertionDisputedCallback = false;
        } catch {
            reverted_assertionDisputedCallback = true;
        }

        // General rule (assert): If this test contract is NOT the optimisticAsserter, then all three calls must revert.
        // If this contract IS the optimisticAsserter (optimisticAsserter == address(this)), then none of them should revert.
        // We observe optimisticAsserter via the public getter c.optimisticAsserter().
        address observed = address(c.optimisticAsserter());

        assert(
            (observed == address(this) && !reverted_requestPrice && !reverted_assertionResolvedCallback && !reverted_assertionDisputedCallback)
            || (observed != address(this) && reverted_requestPrice && reverted_assertionResolvedCallback && reverted_assertionDisputedCallback)
        );
    }

    // allow receiving ether if needed (not used but provided per template)
    receive() external payable {}
}

