contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test entry point. The address parameter is used to simulate a caller
    // by attempting calls via the test contract (msg.sender for c will always be this contract).
    // We check that non-optimistic-asserter callers cannot invoke onlyOptimisticAsserter-protected functions.
    function run(address arbitraryIdentifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(arbitraryIdentifier != address(0), "avoid zero id cast"); // simple precondition on param

        // Prepare inputs cast to expected types
        bytes32 id = bytes32(uint256(uint160(arbitraryIdentifier)));

        // Read the optimisticAsserter address to know who is allowed
        address allowed = address(c.optimisticAsserter());

        // We will try calling the three onlyOptimisticAsserter functions and record whether each reverted.
        bool reqPriceReverted;
