        optimisticCallSucceeded = ok;

        // General rule assertion:
        // - If this contract (not the optimisticAsserter) calls requestPrice it MUST revert (because onlyOptimisticAsserter modifier)
        //   OR optimisticAsserter itself must be able to successfully call requestPrice (so at least one of these holds).
        // This captures the access control: only the optimisticAsserter can successfully call; thus either our direct call reverted
        // (as expected when caller isn't optimisticAsserter) or the optimisticAsserter address is capable of calling successfully.
        assert(revertedFromThis || optimisticCallSucceeded);
    }

