        // We still avoid zero by requiring above and ensuring change.
        if (callerAttempt == optimistic) {
            // flip a bit — produce a different address but keep non-zero
            callerAttempt = address(uint160(uint256(uint160(callerAttempt)) ^ 1));
            if (callerAttempt == address(0)) callerAttempt = address(1);
