        // Otherwise, if optAsserter != address(this), then there exists a valid caller (optAsserter) that would be allowed and thus calling from non-asserter should revert.

        // Our general rule: (optAsserter == address(this)) iff (the direct call did NOT revert).
        // This captures that requestPrice reverts exactly when msg.sender != optimisticAsserter.

        assert((optAsserter == address(this)) == (!reverted_when_not_asserter));
    }

