    constructor(C _c) { c = _c; }

    // single public function with parameters driving calls to c
    function run(address caller, bytes32 identifier, uint256 time, bytes calldata ancillaryData, uint256 sendAmount) public payable {
        require(true);

        // we will attempt to call requestPrice both as an unauthorized caller (this contract) and
        // simulate the authorized caller by calling via the optimisticAsserter getter.
        // Observe: c.requestPrice is protected by onlyOptimisticAsserter, which requires msg.sender == address(optimisticAsserter)
        // So a direct call from this contract should revert, while a call that originates from the optimisticAsserter address would be allowed.

        // First, read the optimisticAsserter address from c
        address optimistic = address(c.optimisticAsserter());

        // Record c balance before any calls
        uint256 beforeBalance = address(c).balance;

        // Try calling requestPrice directly from this contract; it should revert because msg.sender != optimistic
        bool directReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            directReverted = false;
        } catch {
            directReverted = true;
        }

        // Now attempt to call requestPrice with .call using the optimistic address as the caller by crafting a low-level call to the contract address
        // NOTE: We cannot actually change msg.sender to optimistic in a real call. However the contract exposes optimisticAsserter();
        // the only way to exercise the non-revert path is if optimistic == address(this). The general rule must account for that.
        // We'll attempt a low-level call that will succeed only if optimistic == address(this). That keeps the rule general: if optimistic == address(this)
        // then requestPrice must not revert and must not change c.balance; otherwise the direct call must revert.

        // Prepare calldata for requestPrice
        bytes memory payload = abi.encodeWithSelector(c.requestPrice.selector, identifier, time, ancillaryData);
        (bool lowOk, ) = address(c).call{value: 0}(payload);

        // After attempts, record balance
        uint256 afterBalance = address(c).balance;

        // The general rule asserted:
        // - If the optimisticAsserter() equals this contract's address, then calling requestPrice from this contract (low-level) must not revert (lowOk == true).
        // - Otherwise, a direct high-level call must have reverted (directReverted == true).
        // - In all cases, the c contract's balance must remain unchanged by these calls (beforeBalance == afterBalance).
        assert(((optimistic == address(this)) ? (lowOk == true) : (directReverted == true)) && beforeBalance == afterBalance);
    }

    receive() external payable {}
}

